  "ListBox":
      "# A list the user picks one item from (docs/DESIGN.md D46). The program\n# fills it with AddItem and reads it with List, ListCount, ListIndex and\n# Text. Changed runs whenever ListIndex changes: the user picks an item,\n# the program sets ListIndex, or RemoveItem / Clear changes it.\n# Items are set only in code for now (docs/KNOWN_ISSUES.md).\nname: ListBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 160 }\n  - { name: Height, type: Integer, min: 0, default: 120 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\n  # -1 when nothing is chosen; set only while the program runs (D45).\n  - name: ListIndex\n    type: Integer\n    default: -1\n    min: -1\n    designTime: false\n    changeEvent: Changed\n  - { name: ListCount, type: Integer, default: 0, readOnly: true }\n  - { name: Text, type: String, default: \"\", readOnly: true }\n  - { name: Items, type: List(Of String), default: [], internal: true }\nevents:\n  - Changed()\nmethods:\n  - AddItem(item As String)\n  - RemoveItem(index As Integer)\n  - Clear()\n  - List(index As Integer) As String\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  SelectedIndex: ListIndex\n  Items: [AddItem, List, ListCount]\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  SelectedIndexChanged: Changed\n  Click: Changed\n",
  "Menu":
      "# An item of a form's menu bar (docs/DESIGN.md D106), made in the menu\n# editor and written under menus: in the form file. A menu with items in\n# it opens them; an item without opens nothing and raises Click. A\n# Caption of \"-\" is a line between items. Ctrl in a Shortcut is the\n# Command key on macOS. Not seen on the form: the window draws the menu\n# bar, or on macOS the system's menu bar does.\nname: Menu\nversion: 1\nvisual: false\nmenu: true\ndefaultEvent: Click\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Checked, type: Boolean, default: false }\n  - { name: Enabled, type: Boolean, default: true }\n  # False: not on the menu bar, or not in its menu; a menu that is not\n  # Visible can still be shown with PopupMenu.\n  - { name: Visible, type: Boolean, default: true }\n  - { name: Shortcut, type: String, default: \"\", shortcut: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n",
  "OptionButton":
      "# One of a group of choices, of which one is checked (docs/DESIGN.md\n# D104): the OptionButtons of a form are one group. Checking one, by a\n# click or in code, unchecks the others. Changed runs when it becomes\n# checked, as Visual Basic 6's Click did; the ones it unchecks raise\n# nothing, so one handler for the whole group runs once.\nname: OptionButton\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Checked, type: Boolean, default: false, changeEvent: Changed }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 120 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Changed()\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n  Value: Checked\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  CheckedChanged: Changed\n  Click: Changed\n# The type's name in Visual Basic .NET (A056, F020, D104).\naliases: [RadioButton]\n",
  "TextBox":
      "# Changed runs after the text changes, also when the program sets Text\n# (changeEvent). Text holds only the characters the input method (IME)\n# has committed, and Changed runs each time it commits one\n# (docs/LANGUAGE.md §11.1).\nname: TextBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Text, type: String, default: \"\", changeEvent: Changed }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 160 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Changed()\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  TextChanged: Changed\n  Change: Changed\n",
  "Timer":
      "# A Timer runs its Tick every Interval milliseconds while Enabled\n# (docs/DESIGN.md D82, D100). It is not seen on the form: the designer\n# keeps it in a tray under the form, so it has no place or size. A tick\n# is an event like a click: it does not re-enter, and waits while another\n# handler runs. Start and Stop set Enabled.\nname: Timer\nversion: 1\nvisual: false\ndefaultEvent: Tick\nproperties:\n  # How often Tick runs, in milliseconds; at least 1.\n  - { name: Interval, type: Integer, min: 1, default: 100 }\n  # Off at first, as in Visual Basic .NET, so that no tick comes before\n  # Form_Load has set things up.\n  - { name: Enabled, type: Boolean, default: false }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Tick()\nmethods:\n  - Start()\n  - Stop()\n# Names other versions of BASIC use, pointed to GuBASIC's (A036, A051,\n# docs/DESIGN.md D50).\notherEvents:\n  # Visual Basic 6 called the event Timer: Timer1_Timer.\n  Timer: Tick\n",
